"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[5971],{29416:e=>{e.exports=JSON.parse('{"tag":{"label":"Edge AI","permalink":"/labs/tags/edge-ai","allTagsPath":"/labs/tags","count":4,"items":[{"id":"volcano-fire-anomaly","title":"Detecting Volcanic Activity, Fire, and Anomalies Using Advanced AI Models and Edge Computing","description":"Introduction","permalink":"/labs/volcano-fire-anomaly"},{"id":"next-gen-nodes","title":"Next-Generation Nodes for AI","description":"AI is moving fast, and edge hardware is getting powerful and compact. The next-generation node in Sage Grande Testbed (SGT) is built for that exact challenge: bringing high-performance AI where data is created, in the field, in real time, and at scale.","permalink":"/labs/next-gen-nodes"},{"id":"ptz-app","title":"PTZ App: Smarter Cameras for Wildlife and Scene Monitoring","description":"Whether you\'re monitoring wildlife, securing an area, or collecting snapshots from dynamic outdoor scenes, this application helps you do it automatically, intelligently, and efficiently.","permalink":"/labs/ptz-app"},{"id":"sage-mcp","title":"Sage MCP: AI-Powered Edge Computing Interface","description":"In the rapidly evolving landscape of AI and edge computing, accessing complex cyberinfrastructure shouldn\'t require memorizing APIs or writing custom scripts. What if you could simply ask for what you need in plain English? That\'s the vision behind Sage MCP, a Model Context Protocol server that bridges the gap between Large Language Models and the Sage edge computing ecosystem, making advanced sensor networks accessible through natural conversation.","permalink":"/labs/sage-mcp"}],"unlisted":false}}')}}]);